//! F07: the contract suite for `fleet sow --lld <PATH>` (lane contract §7, `docs/lane-contracts/
//! F07-sow-intake.md`). Cargo INTEGRATION test -- drives the real compiled `fleet` binary via
//! subprocess (see `tests/f08_pr_emit.rs` / `tests/s3_lanes.rs` for why a unit test cannot
//! exercise CLI-level exit codes, stderr framing, and `state/sows/` filesystem side effects).
//!
//! Per the lane contract's own instruction to this suite's builder: do not edit this file beyond
//! *adding* cases. Any diff that changes or removes an assertion below is a contract breach.
//!
//! T6/T7/T8/T9/T14 need wrappers that are not checked-in fixtures. Built here at test runtime by
//! loading an existing lead-specified fixture (`complete_freeze.json`, `numeric_trap.json`,
//! `one_line_freeze.json`) and mutating exactly the field each test's own contract row names --
//! composition inside the test, never fixture editing (lane contract §7.1's explicit permission).
//! Every mutation that touches `module_brief` recomputes `content_hash` with the REAL production
//! function (`rehash`, below) before writing the wrapper to disk, or step 3 (this lane's own hash
//! guard) would refuse it for an unrelated reason before the test's own guard is ever reached.

use fleet::lld;
use serde_json::{json, Value};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

fn fleet_bin() -> &'static str {
    env!("CARGO_BIN_EXE_fleet")
}

fn fixtures_dir() -> PathBuf {
    PathBuf::from(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../contracts/fixtures/lld"
    ))
}

fn load_fixture(name: &str) -> Value {
    let text = fs::read_to_string(fixtures_dir().join(format!("{name}.json")))
        .unwrap_or_else(|error| panic!("read fixture {name}: {error}"));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("parse fixture {name}: {error}"))
}

fn unique_dir(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "fleet-f07-{tag}-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    fs::create_dir_all(&dir).expect("create fixture dir");
    dir
}

/// Writes `value` as pretty JSON under a fresh unique temp dir tagged `dir_tag` and returns the
/// file's path.
fn write_temp_json(dir_tag: &str, file_name: &str, value: &Value) -> PathBuf {
    let dir = unique_dir(dir_tag);
    let path = dir.join(file_name);
    fs::write(
        &path,
        serde_json::to_vec_pretty(value).expect("serialize temp fixture"),
    )
    .expect("write temp fixture");
    path
}

/// Recomputes `content_hash` over `wrapper["module_brief"]` with the REAL `lld::content_hash`
/// (never a reimplementation) and writes it into `wrapper["freeze"]["content_hash"]`. Call this
/// after any mutation to `module_brief`.
fn rehash(wrapper: &mut Value) {
    let hash = lld::content_hash(&wrapper["module_brief"])
        .expect("test mutation made module_brief unhashable -- fix the mutation, not this helper");
    wrapper["freeze"]["content_hash"] = Value::String(hash);
}

fn run_sow_lld(state: &Path, lld_path: &Path) -> Output {
    Command::new(fleet_bin())
        .arg("sow")
        .arg("--lld")
        .arg(lld_path)
        .env("FLEET_STATE", state)
        .output()
        .expect("run fleet sow --lld")
}

fn run_sow_task(state: &Path, task: &str) -> Output {
    Command::new(fleet_bin())
        .arg("sow")
        .arg("--task")
        .arg(task)
        .env("FLEET_STATE", state)
        .output()
        .expect("run fleet sow --task")
}

fn run_sow_accept(state: &Path, id: &str) -> Output {
    Command::new(fleet_bin())
        .args(["sow", "accept", "--id", id])
        .env("FLEET_STATE", state)
        .output()
        .expect("run fleet sow accept")
}

fn run_contract_lld_validate(path: &Path) -> Output {
    Command::new(fleet_bin())
        .args(["contract", "lld", "validate"])
        .arg(path)
        .output()
        .expect("run fleet contract lld validate")
}

fn run_gate_lld_ready(path: &Path) -> Output {
    Command::new(fleet_bin())
        .args(["gate", "lld-ready"])
        .arg(path)
        .output()
        .expect("run fleet gate lld-ready")
}

fn stdout_of(out: &Output) -> String {
    String::from_utf8_lossy(&out.stdout).into_owned()
}
fn stderr_of(out: &Output) -> String {
    String::from_utf8_lossy(&out.stderr).into_owned()
}

/// Finds a line starting with `prefix` and returns the value of `key=` within it (mirrors
/// `tests/f08_pr_emit.rs`'s identical helper; duplicated locally per this crate's convention of
/// no shared `tests/common` module).
fn field(text: &str, prefix: &str, key: &str) -> Option<String> {
    text.lines()
        .find_map(|line| line.strip_prefix(prefix))?
        .split_whitespace()
        .find_map(|token| token.split_once('=').filter(|(k, _)| *k == key))
        .map(|(_, v)| v.to_string())
}

fn extract_delimited(text: &str, begin: &str, end: &str) -> Option<String> {
    let start = text.find(begin)? + begin.len();
    let rest = &text[start..];
    let stop = rest.find(end)?;
    Some(rest[..stop].trim_matches('\n').to_string())
}

fn sows_in(state: &Path) -> Vec<PathBuf> {
    fs::read_dir(state.join("sows"))
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.path())
                .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
                .collect()
        })
        .unwrap_or_default()
}

fn load_record(state: &Path, id: &str) -> Value {
    let text = fs::read_to_string(state.join("sows").join(format!("{id}.json")))
        .unwrap_or_else(|error| panic!("read record {id}: {error}"));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("parse record {id}: {error}"))
}

fn cleanup(dirs: &[&Path]) {
    for dir in dirs {
        fs::remove_dir_all(dir).ok();
    }
}

fn normalize_ws(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

// ------------------------------------------------------------------------------------- T1 -----

#[test]
fn f07_t1_complete_freeze_reaches_sow_ready_with_at_least_one_leaf_and_two_alternatives() {
    let state = unique_dir("t1-state");
    let out = run_sow_lld(&state, &fixtures_dir().join("complete_freeze.json"));
    let stderr = stderr_of(&out);
    assert_eq!(out.status.code(), Some(9), "stderr:\n{stderr}");

    let id = field(&stderr, "SOW_READY_AWAITING_REVIEW ", "id").expect("id field on stderr");
    assert_eq!(id.len(), 64, "id must be 64 hex chars: {id:?}");
    assert!(
        id.bytes()
            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()),
        "id must be lowercase hex: {id:?}"
    );
    assert!(
        state.join("sows").join(format!("{id}.json")).exists(),
        "record not written"
    );

    let record = load_record(&state, &id);
    assert!(
        record["sow"]["leaves"]
            .as_array()
            .map(Vec::len)
            .unwrap_or(0)
            >= 1,
        "record: {record}"
    );
    assert!(
        record["sow"]["alternatives"]
            .as_array()
            .map(Vec::len)
            .unwrap_or(0)
            >= 2,
        "record: {record}"
    );
    cleanup(&[&state]);
}

// ------------------------------------------------------------------------------------- T2 -----

#[test]
fn f07_t2_identity_round_trip_produces_the_same_id_via_task_not_exit_mismatch() {
    let state = unique_dir("t2-state");
    let out1 = run_sow_lld(&state, &fixtures_dir().join("complete_freeze.json"));
    let stderr1 = stderr_of(&out1);
    assert_eq!(out1.status.code(), Some(9), "stderr:\n{stderr1}");
    let id1 = field(&stderr1, "SOW_READY_AWAITING_REVIEW ", "id").expect("id field");
    let task_text = extract_delimited(&stderr1, "SOW_LLD_TASK_BEGIN", "SOW_LLD_TASK_END")
        .expect("delimited task text on stderr");

    let out2 = run_sow_task(&state, &task_text);
    let stderr2 = stderr_of(&out2);
    assert_ne!(
        out2.status.code(),
        Some(8),
        "round-trip must not be EXIT_MISMATCH; stderr:\n{stderr2}"
    );
    assert_eq!(out2.status.code(), Some(9), "stderr:\n{stderr2}");
    let id2 = field(&stderr2, "SOW_READY_AWAITING_REVIEW ", "id").expect("id field");
    assert_eq!(id1, id2, "the two intakes produced different SOWs");
    assert_eq!(
        sows_in(&state).len(),
        1,
        "expected exactly one record in state/sows/ after the round-trip"
    );
    cleanup(&[&state]);
}

// ------------------------------------------------------------------------------------- T3 -----

#[test]
fn f07_t3_compiling_the_same_fixture_twice_in_separate_processes_is_byte_identical() {
    let state1 = unique_dir("t3-state-a");
    let state2 = unique_dir("t3-state-b");
    let fixture = fixtures_dir().join("complete_freeze.json");
    let out1 = run_sow_lld(&state1, &fixture);
    let out2 = run_sow_lld(&state2, &fixture);
    let stderr1 = stderr_of(&out1);
    let stderr2 = stderr_of(&out2);
    assert_eq!(out1.status.code(), Some(9), "stderr:\n{stderr1}");
    assert_eq!(out2.status.code(), Some(9), "stderr:\n{stderr2}");

    let text1 = extract_delimited(&stderr1, "SOW_LLD_TASK_BEGIN", "SOW_LLD_TASK_END").unwrap();
    let text2 = extract_delimited(&stderr2, "SOW_LLD_TASK_BEGIN", "SOW_LLD_TASK_END").unwrap();
    assert_eq!(
        text1, text2,
        "compiled task text differs across two separate processes"
    );

    let id1 = field(&stderr1, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    let id2 = field(&stderr2, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    assert_eq!(id1, id2);
    cleanup(&[&state1, &state2]);
}

// ------------------------------------------------------------------------------------- T4 -----

#[test]
fn f07_t4_forged_hash_is_refused_but_both_existing_commands_still_wrongly_pass_it() {
    let forged = fixtures_dir().join("hash_forged_freeze.json");
    let wrapper = load_fixture("hash_forged_freeze");

    // Controls FIRST: prove the hole this lane closes is real, on THIS exact file, before
    // asserting the fix. This is F07 contract §2.1 made mechanical.
    let validate_out = run_contract_lld_validate(&forged);
    assert_eq!(
        validate_out.status.code(),
        Some(0),
        "control: fleet contract lld validate must still pass the forged file (it only checks \
         the hash's PATTERN, never recomputes it); stdout:\n{}",
        stdout_of(&validate_out)
    );

    let brief_path = write_temp_json("t4-brief", "module_brief.json", &wrapper["module_brief"]);
    let gate_out = run_gate_lld_ready(&brief_path);
    assert_eq!(
        gate_out.status.code(),
        Some(0),
        "control: fleet gate lld-ready on the forged file's own brief must still report READY \
         (module_brief itself is untouched by the forgery); stdout:\n{}",
        stdout_of(&gate_out)
    );

    // Now the real fix: `fleet sow --lld` is the first consumer that recomputes the hash.
    let state = unique_dir("t4-state");
    let out = run_sow_lld(&state, &forged);
    let stdout = stdout_of(&out);
    assert_eq!(
        out.status.code(),
        Some(7),
        "stdout:\n{stdout}\nstderr:\n{}",
        stderr_of(&out)
    );
    assert_eq!(
        field(&stdout, "sow_lld_refused: ", "reason").as_deref(),
        Some("FREEZE_HASH_MISMATCH")
    );
    assert!(sows_in(&state).is_empty(), "a refusal must write no record");
    cleanup(&[&state]);
}

