#[test]
fn f07_t5_wrong_stamped_by_is_refused_before_any_record_appears() {
    let state = unique_dir("t5-state");
    let out = run_sow_lld(&state, &fixtures_dir().join("forged_freeze.json"));
    let stderr = stderr_of(&out);
    // Caught at step 2 (shape: `check_freeze` already rejects any `stamped_by` other than the
    // gate's own const) -- EXIT_MISMATCH, same as `fleet contract lld validate` would report,
    // never reaching step 3+. Pinned to the specific code and the specific violation path (not
    // just "non-zero"): a red-on-arrival run against the un-implemented tree showed a bare
    // "non-zero, no record" assertion also passes for the WRONG reason (falling through to the
    // CLI's generic INVALID_SOW_ARGS refusal, exit 7) -- this would not have caught a real
    // regression that made `--lld` silently accept a forged stamp.
    assert_eq!(out.status.code(), Some(8), "stderr:\n{stderr}");
    assert!(
        stderr.contains("freeze.stamped_by"),
        "refusal must name the violated path: {stderr}"
    );
    assert!(sows_in(&state).is_empty());
    cleanup(&[&state]);
}

