#[test]
fn f07_t6_numeric_leaf_in_module_brief_is_refused_as_unhashable_never_a_panic() {
    let mut wrapper = load_fixture("complete_freeze");
    let numeric_trap = load_fixture("numeric_trap");
    let grafted_depth_evidence = numeric_trap["depth_evidence"].clone();
    assert!(
        grafted_depth_evidence.is_object(),
        "numeric_trap.json must carry a depth_evidence object to graft"
    );
    // Grafted into `guarantees[1].derivation`, a location `validate_module_brief` never
    // enumerates or type-checks (it only ever reads `kind`/`calc`/`enforced_by` there) -- so
    // shape validation (step 2) still passes and step 3 (this lane's new hash guard) is what
    // must catch the leaf. This is what makes `unwrap()` on `NumericLeafError` an observable
    // failure mode rather than dead code shape validation would have caught first.
    wrapper["module_brief"]["guarantees"][1]["derivation"]["depth_evidence"] =
        grafted_depth_evidence;
    // Do NOT rehash: the whole point of this test is that module_brief can no longer be hashed.
    assert!(
        lld::validate_lld_v1(&wrapper).is_empty(),
        "construction bug: this mutation must remain shape-valid, or this test exercises shape \
         validation (exit 8) instead of the hash guard (exit 7)"
    );

    let path = write_temp_json("t6-wrapper", "wrapper.json", &wrapper);
    let state = unique_dir("t6-state");
    let out = run_sow_lld(&state, &path);
    let stdout = stdout_of(&out);
    assert_eq!(
        out.status.code(),
        Some(7),
        "stdout:\n{stdout}\nstderr:\n{}",
        stderr_of(&out)
    );
    assert_eq!(
        field(&stdout, "sow_lld_refused: ", "reason").as_deref(),
        Some("FREEZE_UNHASHABLE")
    );
    assert!(sows_in(&state).is_empty());
    cleanup(&[&state]);
}

