#[test]
fn f07_t7_registry_verdict_install_or_extract_short_circuits_before_any_write() {
    for kind in ["install", "extract"] {
        let mut wrapper = load_fixture("complete_freeze");
        let verdict = json!({"kind": kind, "matched_path": "registry/services/llm-gateway"});
        wrapper["module_brief"]["registry"] = verdict.clone();
        wrapper["sow_seed"]["registry_verdict"] = verdict;
        rehash(&mut wrapper);
        assert!(
            lld::validate_lld_v1(&wrapper).is_empty(),
            "construction bug for kind={kind}"
        );

        let path = write_temp_json(&format!("t7-{kind}"), "wrapper.json", &wrapper);
        let state = unique_dir(&format!("t7-{kind}-state"));
        let out = run_sow_lld(&state, &path);
        let stdout = stdout_of(&out);
        assert_eq!(
            out.status.code(),
            Some(7),
            "kind={kind} stdout:\n{stdout}\nstderr:\n{}",
            stderr_of(&out)
        );
        assert_eq!(
            field(&stdout, "sow_lld_refused: ", "reason").as_deref(),
            Some("REGISTRY_REUSE"),
            "kind={kind}"
        );
        assert_eq!(
            field(&stdout, "sow_lld_refused: ", "matched_path").as_deref(),
            Some("registry/services/llm-gateway"),
            "kind={kind}"
        );
        assert!(sows_in(&state).is_empty(), "kind={kind}");
        cleanup(&[&state]);
    }
}

