#[test]
fn f07_t9_readiness_gate_is_actually_invoked_not_skipped_on_the_lld_path() {
    let mut wrapper = load_fixture("complete_freeze");
    let one_line_freeze = load_fixture("one_line_freeze");
    let open_question = one_line_freeze["open_questions"][0].clone();
    assert!(
        open_question.is_string(),
        "one_line_freeze.json must carry a real open question to borrow"
    );
    // Shape only requires open_questions to be an array of strings (any content); C1-OPEN
    // requires it EMPTY. This is a defect ONLY the readiness gate catches -- exactly what
    // isolates "the gate ran and refused" from "shape already refused it" (exit 6 vs exit 8).
    wrapper["module_brief"]["open_questions"] = json!([open_question]);
    rehash(&mut wrapper);
    assert!(
        lld::validate_lld_v1(&wrapper).is_empty(),
        "construction bug: must remain shape-valid so the readiness gate is what's exercised"
    );

    let path = write_temp_json("t9-wrapper", "wrapper.json", &wrapper);
    let state = unique_dir("t9-state");
    let out = run_sow_lld(&state, &path);
    let stderr = stderr_of(&out);
    assert_eq!(
        out.status.code(),
        Some(6),
        "stdout:\n{}\nstderr:\n{stderr}",
        stdout_of(&out)
    );
    assert!(
        stderr.contains("C1-OPEN"),
        "per-check reason must name the failed check on stderr:\n{stderr}"
    );
    assert!(sows_in(&state).is_empty());
    cleanup(&[&state]);
}

