#[test]
fn f07_t10_the_single_leaf_carries_the_predicate_then_text_verbatim() {
    let wrapper = load_fixture("complete_freeze");
    let then_text = wrapper["sow_seed"]["blind_suite_seed"]["predicate"]["then"]
        .as_str()
        .unwrap()
        .to_string();
    // This fixture keeps freeze.accepts_when and sow_seed.blind_suite_seed's predicates
    // identical, so this also equals freeze.accepts_when.predicate.then (the lane contract's
    // own T10 wording) -- recorded here, not depended on: the compiler's real source, per §6.1's
    // table, is sow_seed.blind_suite_seed.
    assert_eq!(
        then_text,
        wrapper["freeze"]["accepts_when"]["predicate"]["then"]
            .as_str()
            .unwrap()
    );

    let state = unique_dir("t10-state");
    let out = run_sow_lld(&state, &fixtures_dir().join("complete_freeze.json"));
    let stderr = stderr_of(&out);
    assert_eq!(out.status.code(), Some(9), "stderr:\n{stderr}");
    let id = field(&stderr, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    let record = load_record(&state, &id);
    let leaves = record["sow"]["leaves"].as_array().expect("leaves array");
    assert_eq!(
        leaves.len(),
        1,
        "exactly one leaf expected from one accepts_when predicate"
    );
    let requirement = leaves[0]["requirement"]
        .as_str()
        .expect("requirement string");
    assert!(
        requirement.contains(&then_text),
        "requirement {requirement:?} does not contain {then_text:?}"
    );
    assert_eq!(
        leaves[0]["acceptance_predicates"].as_array().map(Vec::len),
        Some(1),
        "leaf must carry exactly one predicate: {:?}",
        leaves[0]
    );
    cleanup(&[&state]);
}

