#[test]
fn f07_t11_every_killed_alternative_becomes_one_tradeoff_in_order_none_invented_none_dropped() {
    let wrapper = load_fixture("complete_freeze");
    let killed = wrapper["freeze"]["killed_alternatives"]
        .as_array()
        .unwrap()
        .clone();

    let state = unique_dir("t11-state");
    let out = run_sow_lld(&state, &fixtures_dir().join("complete_freeze.json"));
    let stderr = stderr_of(&out);
    assert_eq!(out.status.code(), Some(9), "stderr:\n{stderr}");
    let id = field(&stderr, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    let record = load_record(&state, &id);
    let alternatives = record["sow"]["alternatives"]
        .as_array()
        .expect("alternatives array");
    assert_eq!(
        alternatives.len(),
        killed.len(),
        "alternative count must match killed_alternatives exactly (>=2 by schema minItems)"
    );
    assert!(alternatives.len() >= 2);
    for (index, (alternative, kill)) in alternatives.iter().zip(killed.iter()).enumerate() {
        let expected = normalize_ws(kill["revive_trigger"].as_str().unwrap());
        let actual = alternative["tradeoff"].as_str().unwrap_or("");
        assert_eq!(actual, expected, "alternatives[{index}].tradeoff mismatch");
    }
    cleanup(&[&state]);
}

