#[test]
fn f07_t13_task_path_is_undisturbed_and_an_lld_record_can_be_accepted() {
    // (a) --task path unaffected: same record shape sow.rs's own tests already exercise, and no
    // lld_provenance key (that field belongs only to the --lld origin).
    let state_task = unique_dir("t13-task-state");
    let good_task = "Task: wire crew.sow into Fleet.\n\
Leaves:\n\
- invoke crew.sow | acceptance: requirement_present(1)\n\
Challenges:\n\
- bridge drift [crew/crew/sow.py:1]\n\
Alternatives:\n\
- Bridge: invoke Python | tradeoff: Python is required\n\
- Port: rewrite in Rust | tradeoff: validation can drift\n\
Estimate:\n\
- 1 engineer-day\n\
Edge cases:\n\
- Python is unavailable";
    let out1 = run_sow_task(&state_task, good_task);
    let stderr1 = stderr_of(&out1);
    assert_eq!(out1.status.code(), Some(9), "stderr:\n{stderr1}");
    let id1 = field(&stderr1, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    let record1 = load_record(&state_task, &id1);
    assert!(
        record1.get("lld_provenance").is_none(),
        "a --task record must never carry lld_provenance: {record1}"
    );
    assert!(record1["accepted"].is_null());
    assert_eq!(record1["id"].as_str(), Some(id1.as_str()));
    assert_eq!(record1["task"].as_str(), Some(good_task));

    // (b) a --lld record can be accepted, and satisfies `accepted_for_exact_task`'s exact logic
    // (sow.rs is not a library module -- this reimplements that pure, total check against the
    // REAL file the REAL binary wrote, rather than importing the private function; the logic is
    // reproduced verbatim from sow.rs's own `accepted_for_exact_task`).
    let state_lld = unique_dir("t13-lld-state");
    let out2 = run_sow_lld(&state_lld, &fixtures_dir().join("complete_freeze.json"));
    let stderr2 = stderr_of(&out2);
    assert_eq!(out2.status.code(), Some(9), "stderr:\n{stderr2}");
    let id2 = field(&stderr2, "SOW_READY_AWAITING_REVIEW ", "id").unwrap();
    let task_text2 = extract_delimited(&stderr2, "SOW_LLD_TASK_BEGIN", "SOW_LLD_TASK_END").unwrap();

    let accept_out = run_sow_accept(&state_lld, &id2);
    assert_eq!(
        accept_out.status.code(),
        Some(0),
        "stdout:\n{}\nstderr:\n{}",
        stdout_of(&accept_out),
        stderr_of(&accept_out)
    );

    let record2 = load_record(&state_lld, &id2);
    assert_eq!(record2["id"].as_str(), Some(id2.as_str()));
    assert_eq!(record2["task"].as_str(), Some(task_text2.as_str()));
    let accepted = &record2["accepted"];
    assert!(accepted["by"].is_string(), "accepted.by: {accepted}");
    assert!(accepted["at"].is_string(), "accepted.at: {accepted}");
    assert!(
        accepted["receipt"].is_string(),
        "accepted.receipt: {accepted}"
    );
    assert!(
        record2.get("lld_provenance").is_some(),
        "acceptance must not drop the provenance this lane attached: {record2}"
    );

    cleanup(&[&state_task, &state_lld]);
}

