#[test]
fn f07_t14a_pipe_in_failure_story_trigger_is_refused_not_silently_mangled() {
    let mut wrapper = load_fixture("complete_freeze");
    wrapper["module_brief"]["failure_story"]["trigger"] =
        json!("the trigger breaks | tradeoff: whatever happens next");
    rehash(&mut wrapper);
    assert!(
        lld::validate_lld_v1(&wrapper).is_empty(),
        "construction bug"
    );

    let path = write_temp_json("t14a-wrapper", "wrapper.json", &wrapper);
    let state = unique_dir("t14a-state");
    let out = run_sow_lld(&state, &path);
    let stdout = stdout_of(&out);
    assert_eq!(
        out.status.code(),
        Some(7),
        "stdout:\n{stdout}\nstderr:\n{}",
        stderr_of(&out)
    );
    assert_eq!(
        field(&stdout, "sow_lld_refused: ", "reason").as_deref(),
        Some("SOW_TEXT_PIPE_COLLISION")
    );
    assert!(sows_in(&state).is_empty());
    cleanup(&[&state]);
}

